--场内现券接口
delete from INTERF_POSITION_CONFIG where TRADE_PLAT = 'TRANS_MATCH' AND INTERF_TYPE IN ('Bond002') and FINPROD_TYPE IN ('F01') AND PS IN ('T01', 'T02', 'T03') AND ENTITY = 'com.joyintech.tams.invest.trade.exchangetransmatch.common.dto.ExchangeTransMatchBaseTradeDto';


--可转债接口
delete from INTERF_POSITION_CONFIG where TRADE_PLAT = 'TRANS_MATCH' AND INTERF_TYPE IN ('Bond003') and FINPROD_TYPE IN ('F01-B14') AND PS IN ('T01', 'T02', 'T03', 'T04', 'T05', 'T97', 'T49') AND ENTITY = 'com.joyintech.tams.invest.trade.exchangetransmatch.common.dto.ExchangeTransMatchBaseTradeDto';


